enum FocusScope {
    #[default]
    Paragraph,
    Line,
    Sentence,
}

impl FocusScope {
    fn title(self) -> &'static str {
        match self {
            FocusScope::Paragraph => "Paragraph",
            FocusScope::Line => "Line",
            FocusScope::Sentence => "Sentence",
        }
    }
}

/// Which pane owns the keyboard for arrow-key navigation. Session-only:
/// clicking a pane or drilling in with Return updates it. The text editor
/// always wins while it has real keyboard focus, so typing never moves
/// the library or sheet cursor.
#[derive(Clone, Copy, PartialEq, Eq, Default, Debug)]
enum PaneFocus {
    #[default]
    Library,
    Sheets,
    Editor,
}

