/// On-disk form of the library. `version` lets future builds migrate.
#[derive(Serialize, Deserialize)]
struct SavedLibrary {
    version: u32,
    groups: Vec<Group>,
    sheets: Vec<Sheet>,
    selection: SidebarSelection,
    selected_sheet: usize,
    #[serde(default)]
    selected_sheets: Vec<usize>,
    /// Raw user-supplied CSS restyling exports. Empty = built-in style.
    #[serde(default)]
    export_css: String,
    /// Display name of the loaded style (file name or "Built-in").
    #[serde(default = "default_style_name")]
    export_css_name: String,
    /// Whether the style guide sheet has been added, so existing libraries
    /// get it exactly once and deleting it is respected.
    #[serde(default)]
    style_guide_added: bool,
    /// Whether the presentation demo sheet has been added, so existing
    /// libraries get it exactly once and deleting it is respected.
    #[serde(default)]
    present_demo_added: bool,
    /// Guide content revision (2 documents `font-family`). Bumped on load so
    /// the surgical refresh below runs once per library.
    #[serde(default)]
    style_guide_version: u32,
    /// User-attached font files (absolute paths). Missing files are skipped
    /// at export time with a status note.
    #[serde(default)]
    attached_fonts: Vec<String>,
    /// Images attached to the library. Files live in the `ariadne-assets`
    /// folder next to the save file; sheets reference them as
    /// `![alt](attachment:<id>)`.
    #[serde(default)]
    attached_images: Vec<AttachedImage>,
    /// The format preselected in the export popover. Remembered across runs.
    #[serde(default)]
    export_format: ExportFormat,
    /// Editor text size in points. Older saves default to the classic 17.
    #[serde(default = "default_editor_font_size")]
    editor_font_size: f32,
    /// Whether the library and sheets sidebars are shown. Predates the
    /// per-sidebar split; applies to both when the fields below are
    /// absent. Still written so the file stays self-describing.
    #[serde(default = "default_true")]
    sidebars_visible: bool,
    /// Per-sidebar visibility. `None` (older saves) falls back to the
    /// legacy flag above.
    #[serde(default)]
    library_visible: Option<bool>,
    /// Per-sidebar visibility. `None` (older saves) falls back to the
    /// legacy flag above.
    #[serde(default)]
    sheets_visible: Option<bool>,
    /// Writing-goal target in words. `0` (and absent in older saves) means
    /// no goal is set yet.
    #[serde(default)]
    word_goal: u32,
    /// App chrome color scheme. Absent in older saves: they stay dark.
    #[serde(default)]
    app_theme: AppTheme,
    /// Editor font family (a system font name). `None` (and absent in
    /// older saves) means the built-in proportional font.
    #[serde(default)]
    editor_font_family: Option<String>,
    /// Deleted sheet/group UUIDs with their sections. Sync never resurrects
    /// these. Each store file tracks its own sections. Absent in older saves.
    #[serde(default)]
    tombstones: Vec<Tombstone>,
    /// Global sheet order as UUIDs, preserving the merged order across the
    /// per-section file split. Unknown UUIDs append in file order on load.
    /// Absent in older saves (falls back to file order).
    #[serde(default)]
    sheet_order: Vec<String>,
    /// UUID of the selected group or sheet, if any. Remaps the index-based
    /// `selection` after a merge shifts positions. Absent in older saves.
    #[serde(default)]
    selection_id: Option<String>,
    /// UUID of the focused sheet. Remaps `selected_sheet`. Absent in older
    /// saves.
    #[serde(default)]
    selected_sheet_id: Option<String>,
    /// UUIDs of the multi-selected sheets, in order. Remaps
    /// `selected_sheets`. Absent in older saves.
    #[serde(default)]
    selected_sheets_ids: Vec<String>,
    /// Explicit iCloud store directory (synced `library.json` + mirror tree
    /// live here). `None` means automatic: the iCloud Drive folder when
    /// available, else a local fallback next to the library. Absent in
    /// older saves.
    #[serde(default)]
    icloud_dir: Option<String>,
    /// Check spelling and grammar as you type. Absent in older saves: on.
    #[serde(default = "default_true")]
    grammar_enabled: bool,
    /// Custom slide background colors as `#rrggbb`. Slides rotate through
    /// them (`slide i` uses `colors[i % len]`); empty means the app theme.
    #[serde(default)]
    present_colors: Vec<String>,
    /// Legacy single slide font (replaced by header/body below). Kept so
    /// older saves still load; migrated to both fonts when they are unset.
    #[serde(default)]
    present_font_family: Option<String>,
    /// Custom slide header font family (a system font name). `None` = built-in.
    #[serde(default)]
    present_header_font: Option<String>,
    /// Custom slide body font family (a system font name). `None` = built-in.
    #[serde(default)]
    present_body_font: Option<String>,
    /// Slide aspect ratio for presenter exports. Absent in older saves:
    /// widescreen 16:9.
    #[serde(default)]
    present_aspect: PresentAspect,
    /// Typewriter scrolling: keep the caret line centered. Absent in
    /// older saves: off.
    #[serde(default)]
    typewriter: bool,
    /// Focus mode: dim paragraphs outside the caret's. Absent in older
    /// saves: off.
    #[serde(default)]
    focus_mode: bool,
    /// What focus mode keeps bright: paragraph, line, or sentence.
    #[serde(default)]
    focus_scope: FocusScope,
    /// Whether the style sidebar is shown. Remembered across runs.
    #[serde(default)]
    style_visible: bool,
    /// Creation timestamps keyed by sheet UUID. Kept outside `Sheet` so
    /// older saves and sync merges need no migration; a missing entry
    /// falls back to the sheet's `modified` time.
    #[serde(default)]
    created_dates: std::collections::HashMap<String, SystemTime>,
    /// Per-group presentation (icon, color, sorting) keyed by group UUID.
    #[serde(default)]
    group_styles: std::collections::HashMap<String, GroupStyle>,
    /// Library-wide keyword presentation (color, favorite) keyed by the
    /// lowercased keyword text.
    #[serde(default)]
    keyword_styles: std::collections::HashMap<String, KeywordStyle>,
    /// Custom dictionary additions, synced across devices via the union
    /// merge below (either side may add words independently).
    #[serde(default)]
    dictionary_adds: Vec<String>,
    /// Daily word target. `0` = no daily goal.
    #[serde(default)]
    daily_goal: u32,
    /// Optional project deadline for required-daily-output calculations.
    #[serde(default)]
    deadline: Option<SystemTime>,
    /// Total word target for the deadline (e.g. 80,000 for a novel).
    #[serde(default)]
    deadline_target: u32,
    /// Positive words added per day (`YYYY-MM-DD` UTC), for the history
    /// chart and the daily-session metric store.
    #[serde(default)]
    daily_words: std::collections::HashMap<String, u64>,
    /// Words removed from the custom dictionary. A word in both lists
    /// counts as removed, so un-learning propagates too.
    #[serde(default)]
    dictionary_removes: Vec<String>,
    /// Set when loading merged in remote changes: the app saves immediately
    /// to converge the stores. Session-only, never persisted.
    #[serde(skip)]
    dirty: bool,
}

/// One image attached to the library.
