/// The CSS for a virtual style, if `name` is one.
fn virtual_style_css(name: &str) -> Option<&'static str> {
    VIRTUAL_STYLES
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, css)| *css)
}

/// Names that can never be saved files: the default look plus the virtuals.
fn is_reserved_style(name: &str) -> bool {
    name == "Built-in" || virtual_style_css(name).is_some()
}

/// Persisted main-window geometry: content size plus outer position.
/// Lives in `window.json` next to `library.json` (never synced), so the
/// app reopens where the user left it.
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
struct WindowState {
    width: f32,
    height: f32,
    #[serde(default)]
    x: Option<f32>,
    #[serde(default)]
    y: Option<f32>,
    #[serde(default)]
    maximized: bool,
    /// Interface scale for this display. Lives with the window geometry
    /// because it is a per-machine/display preference, not library data.
    #[serde(default = "default_ui_scale")]
    ui_scale: f32,
    /// Multiplier applied to wheel/trackpad scrolling.
    #[serde(default = "default_scroll_speed")]
    scroll_speed: f32,
}

impl WindowState {
    /// Inner size handed to the viewport builder. Width/height are stored
    /// as logical points at `ui_scale`, but winit interprets the builder in
    /// native-scale points, so the zoom is undone here. Without this, every
    /// restart would open a window `ui_scale` times too small and each
    /// restart would shrink it again.
    fn builder_size(self) -> egui::Vec2 {
        let z = sanitize_ui_scale(self.ui_scale);
        egui::Vec2::new(self.width * z, self.height * z)
    }

    /// Outer position for the viewport builder, in the same native-scale
    /// points as [`Self::builder_size`].
    fn builder_pos(self) -> Option<egui::Vec2> {
        let z = sanitize_ui_scale(self.ui_scale);
        Some(egui::Vec2::new(self.x? * z, self.y? * z))
    }

    /// Validate loaded values: sizes must be finite (clamped to sane
    /// bounds), positions must be finite or dropped. Returns `None` when
    /// the size itself is unusable.
    fn sanitized(mut self) -> Option<Self> {
        if !self.width.is_finite() || !self.height.is_finite() {
            return None;
        }
        self.width = self.width.clamp(400.0, 5000.0);
        self.height = self.height.clamp(300.0, 5000.0);
        self.ui_scale = sanitize_ui_scale(self.ui_scale);
        self.scroll_speed = sanitize_scroll_speed(self.scroll_speed);
        if let Some(x) = self.x {
            if !x.is_finite() || x < -10000.0 || x > 10000.0 {
                self.x = None;
            }
        }
        if let Some(y) = self.y {
            if !y.is_finite() || y < -10000.0 || y > 10000.0 {
                self.y = None;
            }
        }
        Some(self)
    }
}

/// Last-written state of one iCloud/Drive mirror file, so unchanged saves
/// can skip re-reading it. Keyed by the destination path.
struct MirrorFileState {
    // File metadata uses std's clock even on wasm (our `SystemTime` alias
    // is web_time there, which is a different type).
    mtime: Option<std::time::SystemTime>,
    len: u64,
    hash: u64,
}

/// Last-copied state of one mirrored attachment. Both source and
/// destination metadata are compared, so a changed file is re-copied.
struct MirrorAssetState {
    src_mtime: Option<std::time::SystemTime>,
    src_len: u64,
    dst_mtime: Option<std::time::SystemTime>,
    dst_len: u64,
}

/// Irreversible action waiting for the confirmation modal.
enum ConfirmDelete {
    /// Permanently delete one sheet, identified by UUID so list shifts
    /// while the modal is open cannot target the wrong sheet.
    SheetForever(String),
    EmptyTrash,
}

struct WritingApp {
    groups: Vec<Group>,
    sheets: Vec<Sheet>,
    selection: SidebarSelection,
    selected_sheet: usize,
    /// Multi-selection for the middle panel / editor / export. `selected_sheet`
    /// stays the focused (primary) sheet so old save files keep working.
    selected_sheets: Vec<usize>,
    /// Sheet UUIDs visited before/after the current one, for Back/Forward.
    /// Session-only: resolved by UUID so reorders and merges cannot misjump.
    nav_back: Vec<String>,
    nav_forward: Vec<String>,
    /// Raw user-supplied CSS restyling exports. Empty = built-in style.
    export_css: String,
    /// Display name of the loaded style (file name or "Built-in").
    export_css_name: String,
    /// Whether the style guide sheet has been added, so existing libraries
    /// get it exactly once and deleting it is respected.
    style_guide_added: bool,
    /// Whether the presentation demo sheet has been added, so existing
    /// libraries get it exactly once and deleting it is respected.
    present_demo_added: bool,
    /// Guide content revision (2 documents `font-family`).
    style_guide_version: u32,
    /// User-attached font files (absolute paths), matched by family name
    /// ahead of system fonts. Bytes are read at export time, never stored.
    attached_fonts: Vec<String>,
    /// Image registry. The files live in the assets folder; sheets refer to
    /// them as `![alt](attachment:<id>)`.
    attached_images: Vec<AttachedImage>,
    /// Lazily built system font index. Skipped when it would be empty.
    font_db: Option<fontdb::Database>,
    /// GPU textures for previewed images, keyed by content hash.
    image_textures: std::collections::HashMap<String, egui::TextureHandle>,
    /// Open in-app style editor, if any.
    style_editor: Option<StyleEditState>,
    /// Format preselected in the export popover.
    export_format: ExportFormat,
    /// Editor text size in points. Adjustable from Settings.
    editor_font_size: f32,
    /// Interface scale (zoom factor) for this display. Persisted with the
    /// window geometry so different screens can use different scales.
    ui_scale: f32,
    /// Last scale applied to egui, so setting it does not fight in-session
    /// Ctrl+Plus/Minus zoom. Session-only.
    applied_ui_scale: f32,
    /// Multiplier applied to smooth wheel/trackpad scrolling.
    scroll_speed: f32,
    /// Inner window size in points from the current frame. Wayland gives
    /// clients no window position, so egui's `viewport().inner_rect` is
    /// absent there; this is the fallback size used to persist geometry
    /// and preferences. Session-only.
    last_viewport_size: Vec2,
    /// Typewriter scrolling: keep the caret line centered. Remembered.
    typewriter: bool,
    /// Focus mode: dim paragraphs outside the caret's. Remembered.
    focus_mode: bool,
    /// Region focus mode keeps bright (paragraph, line, or sentence).
    focus_scope: FocusScope,
    /// Zen mode: hide all chrome (headerbar, sidebars, status bar) and
    /// show only the editor. Session-only: always starts off, never
    /// persisted, so a restart can never trap the app chromeless.
    zen_mode: bool,
    /// Whether the library sidebar is shown. Remembered across runs;
    /// toggled from the headerbar or with a two-finger swipe.
    library_visible: bool,
    /// Whether the sheets sidebar is shown. Remembered across runs;
    /// the swipe gesture opens this one first and closes it last.
    sheets_visible: bool,
    /// Target word count for the writing-goal sidebar. `0` = no goal set.
    /// Remembered across runs.
    word_goal: u32,
    /// Daily word target. `0` = no daily goal. Remembered across runs.
    daily_goal: u32,
    /// Optional project deadline (UTC date). Remembered across runs.
    deadline: Option<SystemTime>,
    /// Total word target for the deadline. `0` = not set.
    deadline_target: u32,
    /// Positive words added per day (`YYYY-MM-DD` UTC). Persisted and
    /// included in project archives; the chart and daily goal read it.
    daily_words: std::collections::HashMap<String, u64>,
    /// Library word count at the last metric tick, for turning edits into
    /// a daily words-written delta. Session-only.
    last_counted_words: Option<u64>,
    /// `ctx.time()` of the last metric tick (throttles the full recount).
    last_metrics_tick: f64,
    /// `ctx.time()` of the last daily-store save (throttles disk writes).
    last_metrics_save: f64,
    /// Whether the writing-goal sidebar is shown. Session-only: always
    /// starts collapsed and is never persisted.
    goals_visible: bool,
    /// Sheets-panel hover target from the previous frame (cards and header
    /// buttons brighten on hover). Session-only, reset every frame before
    /// the panel paints.
    sheets_hover: Option<SheetHover>,
    /// Creation timestamps keyed by sheet UUID. Missing entries fall back
    /// to `modified` (older saves never recorded a creation date).
    created_dates: std::collections::HashMap<String, SystemTime>,
    /// Per-group icon, color and sheet ordering keyed by group UUID.
    group_styles: std::collections::HashMap<String, GroupStyle>,
    /// Library-wide keyword colors and favorites keyed by lowercased text.
    keyword_styles: std::collections::HashMap<String, KeywordStyle>,
    /// Whether the keyword manager window is open. Session-only.
    keywords_open: bool,
    /// Pane owning arrow-key navigation (library, sheets, or editor).
    /// Session-only; the focused text editor always takes precedence.
    pane_focus: PaneFocus,
    /// Whether the starter-project template picker is open. Session-only.
    templates_open: bool,
    /// Whether the two-editor split view is open. Session-only.
    split_open: bool,
    /// Side-by-side (true) or stacked (false) split layout.
    split_side_by_side: bool,
    /// Sheet shown in the secondary pane. Session-only.
    split_sheet: Option<usize>,
    /// Open table editor, if any. Session-only.
    table_editor: Option<TableEditorState>,
    /// Focused review state: dims the text, hides the library pane, and
    /// opens the Review tab. Session-only (never persisted); the previous
    /// pane/mode state is restored when it is turned off.
    revision_mode: bool,
    /// Saved UI state to restore when revision mode ends:
    /// (library_visible, sheets_visible, focus_mode, goals, style, history).
    revision_prev: Option<(bool, bool, bool, bool, bool, bool)>,
    /// App chrome color scheme. Remembered across runs.
    app_theme: AppTheme,
    /// Effectively active chrome (built-in or custom), recomputed every
    /// frame. Paint code reads this; the setting above stays untouched.
    theme: ResolvedTheme,
    /// User-built themes, persisted per-machine in `themes.json`.
    custom_themes: Vec<custom_theme::CustomTheme>,
    /// Active custom theme id, if any. `None` = the built-in `app_theme`.
    active_custom: Option<String>,
    /// Live preview keys while the theme editor is open. Session-only.
    theme_draft: Option<custom_theme::CustomKeys>,
    /// Open theme editor state, if any. Session-only.
    theme_editor: Option<ThemeEditorState>,
    /// Editor font family (a system font name). `None` = built-in font.
    /// Remembered across runs.
    editor_font_family: Option<String>,
    /// Explicit iCloud store directory override (Settings → Move). Mirrors
    /// the persisted anchor in the local library file. `None` = automatic.
    icloud_dir: Option<String>,
    /// Which family is currently loaded into egui, if any. Session-only:
    /// reloaded from `editor_font_family` after restarts.
    loaded_editor_font: Option<String>,
    /// Preview families already queued for loading (binding applies the
    /// next pass; see `preview_font`). Session-only.
    preview_fonts_queued: std::collections::HashSet<String>,
    /// Whether the settings window is open. Session-only.
    settings_open: bool,
    /// Selected tab in the settings window. Session-only.
    settings_tab: SettingsTab,
    /// Uncommitted word-goal text typed in the goals sidebar. Committed
    /// with Set/Enter so typing never fights live updates. Session-only.
    goal_draft: String,
    /// Whether the outline popup is open. Session-only.
    outline_open: bool,
    /// Two-finger swipe accumulator (device px) for sidebar control.
    swipe_accum_x: f32,
    swipe_accum_y: f32,
    /// `ctx.time()` until which swipe input is swallowed (post-fire momentum).
    swipe_cooldown_until: f64,
    /// Whether the export popover is open.
    show_export_popover: bool,
    /// Whether the sheet search popup is open. Session-only.
    search_open: bool,
    /// Current search text; while non-empty the sheets panel shows only
    /// matches. Session-only: cleared when the popup closes.
    search_query: String,
    /// Highlighted search result for arrow-key navigation. Session-only:
    /// reset whenever the query changes.
    search_cursor: usize,
    /// In-document find bar: open state, query, case toggle, current hit,
    /// and highlight ranges for the selected sheet. Session-only.
    find_open: bool,
    find_query: String,
    /// Replacement text for the find bar's Replace actions. Session-only.
    find_replace: String,
    /// One-step undo for find-bar replaces: the sheet plus its content
    /// before and after. Applies only if the sheet is otherwise untouched.
    /// Session-only, cleared on close.
    find_undo: Option<FindUndo>,
    find_case: bool,
    find_index: usize,
    find_matches: Vec<(usize, usize)>,
    find_scroll: bool,
    /// Typewriter scrolling + focus mode (Settings → Editor). Remembered.
    /// Last centered (sheet, galley row), so scrolling only recenters on
    /// caret moves and never fights the mouse wheel. Session-only.
    typewriter_last: Option<(usize, usize)>,
    /// Request keyboard focus in the search field on the next frame.
    search_focus: bool,
    /// Whether the history popup is open. Session-only.
    history_open: bool,
    /// Group being renamed inline in the library list, if any.
    /// Stored by UUID so list reorders can't desync it. Session-only:
    /// cancelled on selection change, never persisted.
    group_rename: Option<String>,
    /// Editable draft of the renamed group's title.
    group_rename_draft: String,
    /// Request keyboard focus (plus select-all) in the rename field once.
    group_rename_focus: bool,
    /// Saved versions of sheet contents, keyed by sheet index. Bounded per
    /// sheet; persisted to a sidecar file next to the library.
    history: std::collections::HashMap<usize, Vec<Snapshot>>,
    /// Whether the live export preview window (separate OS window) is open.
    /// Session-only: never persisted, never screenshotted.
    preview_window_open: bool,
    /// Set once per opening so the window is placed beside the main one
    /// without being repositioned every frame.
    preview_window_placed: bool,
    /// Whether the presentation audience window (separate OS window) is
    /// open. Session-only: the main window becomes the presenter console
    /// while this is open.
    present_window_open: bool,
    /// Set once per opening so the audience window is placed beside the
    /// main one without being repositioned every frame.
    present_window_placed: bool,
    /// Sheet under presentation (`sheets` index at open time). `None` when
    /// the sheet list is empty.
    present_sheet: Option<usize>,
    /// Current slide index within the live slide list.
    present_index: usize,
    /// Whether speaker notes show in the presenter console. Session-only.
    present_notes_visible: bool,
    /// `ctx.input(|i| i.time)` snapshot when the current presentation
    /// started, for the elapsed timer. Session-only.
    present_started_at: Option<f64>,
    /// Export toggle: emit the handout article (one section per slide with
    /// speaker notes as body text) instead of the plain export.
    /// Session-only.
    handout_notes: bool,
    /// Custom slide background colors as `#rrggbb`. Slides rotate through
    /// them; empty means the app theme. Remembered across runs.
    present_colors: Vec<String>,
    /// Legacy single slide font (replaced by header/body). Kept for
    /// migration; new saves leave it as `None`.
    present_font_family: Option<String>,
    /// Custom slide header font family (a system font name). `None` = built-in.
    /// Remembered across runs.
    present_header_font: Option<String>,
    /// Custom slide body font family (a system font name). `None` = built-in.
    /// Remembered across runs.
    present_body_font: Option<String>,
    /// Slide aspect ratio for presenter exports. Remembered across runs.
    present_aspect: PresentAspect,
    /// Selected tab in the presenter console. Session-only.
    present_tab: PresentTab,
    /// Draft Coolors palette link typed in the Style tab. Session-only:
    /// never persisted; cleared after a successful import.
    coolors_draft: String,
    /// Laid-out live preview, rebuilt when the inputs change.
    preview_cache: PreviewCache,
    /// Cached presenter deck (parsed slides + layouts). Session-only.
    present_slides_cache: Option<PresentSlidesCache>,
    /// Sorted system font families, cached after first load. Session-only.
    cached_font_families: Option<Vec<String>>,
    /// Background system-font scan receiver. Session-only.
    font_db_rx: Option<std::sync::mpsc::Receiver<fontdb::Database>>,
    /// Finished presenter export bytes from the worker thread. Session-only.
    present_export_rx: Option<std::sync::mpsc::Receiver<PresentExportResult>>,
    /// Save metadata while the worker thread renders. Session-only.
    present_export_pending: Option<PresentExportPending>,
    /// Finished document-export bytes from the worker thread. Session-only.
    export_rx: Option<std::sync::mpsc::Receiver<ExportWorkerResult>>,
    /// Where the finished document export should go. Session-only.
    export_pending: Option<ExportPending>,
    /// Image decodes allowed this frame (budget spreads work). Session-only.
    image_decodes_this_frame: usize,
    /// Background presenter-image decode worker. Session-only.
    present_image_tx: Option<std::sync::mpsc::Sender<PresentImageJob>>,
    /// Finished background decodes, uploaded on the UI thread. Session-only.
    present_image_rx: Option<std::sync::mpsc::Receiver<PresentDecodedImage>>,
    /// Image `src`s with a decode in flight (never double-queue). Session-only.
    present_image_pending: std::collections::HashSet<String>,
    /// Image `src`s proven missing/undecodable (permanent placeholder,
    /// never requeued). Session-only.
    present_image_failed: std::collections::HashSet<String>,
    /// Frames since presenter mode opened. Images are not even queued until
    /// the shell has painted (~2 frames), so the console + audience window
    /// appear instantly with placeholders and images pop in after.
    /// Session-only.
    present_open_ticks: usize,
    /// Resolved image bytes cache (`src` -> bytes + kind). Session-only.
    image_bytes_cache:
        std::cell::RefCell<std::collections::HashMap<String, Option<(Vec<u8>, String)>>>,
    /// Decoded image dimensions cache (`src` -> w/h). Session-only.
    image_dims_cache: std::cell::RefCell<std::collections::HashMap<String, Option<(u32, u32)>>>,
    /// Last local-save failure, if any. Drives the status bar and retry.
    /// Session-only: cleared by the next successful write.
    save_error: Option<String>,
    /// An autosave is scheduled but not written yet. Session-only.
    save_pending: bool,
    /// When the deferred autosave becomes due. Session-only.
    save_due: Option<Instant>,
    /// Earliest time to retry after a failed save. Session-only.
    save_retry_at: Option<Instant>,
    /// Mirror files last written, so an unchanged save only stats them
    /// instead of re-reading every `.md`. Session-only.
    mirror_files: std::collections::HashMap<PathBuf, MirrorFileState>,
    /// Mirror attachments last copied, keyed by destination path.
    mirror_assets: std::collections::HashMap<PathBuf, MirrorAssetState>,
    /// Pending irreversible action awaiting confirmation. Session-only.
    confirm_delete: Option<ConfirmDelete>,
    /// Per-sheet metrics (words, chars) keyed by UUID. Session-only.
    metrics_cache:
        std::cell::RefCell<std::collections::HashMap<String, (SystemTime, usize, usize)>>,
    /// Per-sheet card title + preview keyed by UUID. Session-only.
    card_cache:
        std::cell::RefCell<std::collections::HashMap<String, (SystemTime, Arc<(String, String)>)>>,
    /// Per-sheet lowercased body, for search without re-lowercasing every
    /// frame. Session-only.
    lower_cache: std::cell::RefCell<std::collections::HashMap<String, (SystemTime, Arc<String>)>>,
    /// Per-sheet parsed internal links keyed by UUID. Session-only.
    links_cache: std::cell::RefCell<
        std::collections::HashMap<String, (SystemTime, Arc<Vec<(String, String)>>)>,
    >,
    /// Dashboard backlink scan for one target sheet, keyed by a library
    /// stamp and target UUID. Session-only.
    backlinks_cache: std::cell::RefCell<Option<(u64, String, Arc<Vec<(String, String)>>)>>,
    status: String,
    screenshot_path: Option<PathBuf>,
    frame_count: u32,
    screenshot_requested: bool,
    caret_blink_start: f64,
    caret_key: (usize, usize),
    /// Deleted sheet/group UUIDs with their sections. Saved split by
    /// section into each store file. Session-persisted via save/load.
    tombstones: Vec<Tombstone>,
    /// Last seen content hash per store ("local", "icloud"). Detects
    /// external changes (another device) before each save so merges run
    /// instead of blind overwrites. Session-only.
    sync_hashes: std::collections::HashMap<String, u64>,
    /// `ctx.time()` of the last background sync check. Session-only.
    last_sync_check: f64,
    /// Whether the sync-conflict review popup is open. Session-only.
    show_conflicts: bool,
    /// Google Drive sync session. Session-only: tokens stay in the keychain.
    gdrive: GdriveSync,
    /// In-app update check state. Prefs persist in `update.json`; the
    /// check result itself is session-only.
    update_state: UpdateState,
    /// Grammar state: checker, per-sheet lint cache, ignores. The
    /// dictionary words themselves live here too (persisted + synced).
    grammar: GrammarState,
    /// Last persisted main-window geometry. Session-only: seeded from
    /// `window.json` at startup, updated as the window moves/resizes.
    last_window_state: Option<WindowState>,
    /// `ctx.time()` of the last window-geometry write. Throttles drags.
    last_window_save: f64,
    /// `ctx.time()` of the first window-geometry observation. Disk writes
    /// are skipped for ~1s after startup so transient first frames can
    /// never clobber a good `window.json`.
    window_t0: Option<f64>,
}

/// Google Drive connection state. Session-only.
#[derive(Default)]
struct GdriveSync {
    worker: Option<GdriveWorker>,
    mode: GdriveMode,
    /// Account email from userinfo, once known.
    email: String,
    /// Last successful push or pull.
    last_synced: Option<SystemTime>,
    /// Whether the remote folder is known to exist (seen via pull/push).
    /// Stays false until first contact so an empty section never summons
    /// the Drive folder.
    remote_exists: bool,
    /// A job is in flight; saves coalesce into one pending push.
    busy: bool,
    pending_push: bool,
    /// Time of the last local save (push quiet period).
    last_edit: Option<SystemTime>,
    /// `ctx.time()` of the last Drive poll.
    last_poll: f64,
}

impl GdriveSync {
    /// Seconds since the last local save; unknown counts as long ago.
    fn quiet_since_save(&self) -> f64 {
        self.last_edit
            .and_then(|t| SystemTime::now().duration_since(t).ok())
            .map(|d| d.as_secs_f64())
            .unwrap_or(f64::MAX)
    }
}

