    #[test]
    fn interface_prefs_persist_as_soon_as_they_change() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.last_window_state = Some(WindowState {
            width: 1100.0,
            height: 720.0,
            x: None,
            y: None,
            maximized: false,
            ui_scale: 1.0,
            scroll_speed: 1.75,
        });
        // Changing the scale writes window.json immediately: quitting by
        // crash/logout must not lose it.
        app.set_ui_scale(1.5);
        let saved = WritingApp::load_window_state().expect("window state written");
        assert!((saved.ui_scale - 1.5).abs() < 0.001);
        assert_eq!(saved.width, 1100.0, "geometry preserved");
        // The scroll speed rides along and keeps the scale.
        app.set_scroll_speed(2.5);
        let saved = WritingApp::load_window_state().unwrap();
        assert!((saved.ui_scale - 1.5).abs() < 0.001);
        assert!((saved.scroll_speed - 2.5).abs() < 0.001);
        // Even without tracked geometry in memory, an existing file is
        // updated rather than skipped.
        let mut fresh = sample_app();
        fresh.last_window_state = None;
        fresh.ui_scale = 1.25;
        fresh.set_scroll_speed(3.0);
        let saved = WritingApp::load_window_state().unwrap();
        assert!((saved.ui_scale - 1.25).abs() < 0.001);
        assert!((saved.scroll_speed - 3.0).abs() < 0.001);
        // Screenshot runs never touch the user's file.
        let mut shot = sample_app();
        shot.screenshot_path = Some(std::path::PathBuf::from("/tmp/shot.png"));
        shot.set_ui_scale(2.0);
        assert!((WritingApp::load_window_state().unwrap().ui_scale - 1.25).abs() < 0.001);
        // Wayland-like: no window position (egui's inner_rect is empty), no
        // file yet, but the frame size is known. Preferences still persist
        // with a size-only geometry and no position.
        clear_window_state();
        let mut wayland = sample_app();
        wayland.last_viewport_size = egui::vec2(1000.0, 700.0);
        wayland.set_ui_scale(1.1);
        let saved = WritingApp::load_window_state().expect("written from screen size");
        assert!((saved.ui_scale - 1.1).abs() < 0.001);
        assert_eq!((saved.width, saved.height), (1000.0, 700.0));
        assert!(saved.x.is_none() && saved.y.is_none());
        clear_window_state();
    }

    #[test]
    fn keyboard_zoom_is_adopted_and_persisted() {
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        WritingApp::save_window_state(&WindowState {
            width: 1100.0,
            height: 720.0,
            x: None,
            y: None,
            maximized: false,
            ui_scale: 1.25,
            scroll_speed: 1.75,
        });
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        harness.run();
        // A restart adopts the saved scale and applies it to the context.
        assert!((harness.state().ui_scale - 1.25).abs() < 0.001);
        assert!((harness.ctx.zoom_factor() - 1.25).abs() < 0.001);
        // egui's built-in Ctrl +/- changes the context zoom directly.
        harness.ctx.set_zoom_factor(1.5);
        harness.run();
        assert!(
            (harness.state().ui_scale - 1.5).abs() < 0.001,
            "keyboard zoom should sync the setting, got {}",
            harness.state().ui_scale
        );
        let saved = WritingApp::load_window_state().expect("window state written");
        assert!((saved.ui_scale - 1.5).abs() < 0.001);
        clear_window_state();
    }

