    #[test]
    fn markup_actions_wrap_and_toggle() {
        let (out, a, b) = WritingApp::apply_markup("hello world", 0, 5, MarkupKind::Bold);
        assert_eq!(out, "**hello** world");
        assert_eq!((a, b), (2, 7));
        let (back, _, _) = WritingApp::apply_markup(&out, 2, 7, MarkupKind::Bold);
        assert_eq!(back, "hello world");
        let (link, a, b) = WritingApp::apply_markup("hello", 0, 5, MarkupKind::Link);
        assert_eq!(link, "[hello](https://)");
        assert_eq!(&link[link.char_indices().nth(a).unwrap().0..], "https://)");
        assert_eq!(b - a, 8);
        let (quote, _, _) = WritingApp::apply_markup("one\ntwo", 0, 7, MarkupKind::Quote);
        assert_eq!(quote, "> one\n> two");
        let (plain, _, _) =
            WritingApp::apply_markup(&quote, 0, quote.chars().count(), MarkupKind::Quote);
        assert_eq!(plain, "one\ntwo");
        let (heading, _, _) = WritingApp::apply_markup("Title", 0, 5, MarkupKind::Heading);
        assert_eq!(heading, "# Title");
    }

