    #[test]
    fn theme_grid_renders_and_switches_every_theme() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        // Appearance is the default settings tab: the theme grid renders
        // on open.
        harness.state_mut().settings_open = true;
        harness.run();

        for theme in AppTheme::all() {
            // Every theme paints full frames without panicking, with
            // readable text and the expected dark/light polarity.
            harness.state_mut().app_theme = theme;
            harness.run();
            harness.run();
            let p = theme.palette();
            assert_ne!(p.text_main, p.bg_app, "{theme:?} text unreadable");
            assert_ne!(p.accent, p.bg_app, "{theme:?} accent invisible");
            // Library sidebar reads as its own column: distinct from
            // both the headerbar and the sheets panel.
            assert_ne!(
                p.bg_sidebar, p.bg_panel,
                "{theme:?} sidebar blends into header"
            );
            assert_ne!(
                p.bg_sidebar, p.bg_sheets,
                "{theme:?} sidebar blends into sheets"
            );
            assert_eq!(
                theme.is_dark(),
                !matches!(
                    theme,
                    AppTheme::Light
                        | AppTheme::GruvboxLight
                        | AppTheme::NordLight
                        | AppTheme::CatppuccinLatte
                        | AppTheme::RosePineDawn
                        | AppTheme::EverforestLight
                        | AppTheme::Solarized
                        | AppTheme::TokyoNightDay
                ),
                "{theme:?} polarity"
            );
        }

        // Clicking a grid entry switches and persists the theme.
        harness.state_mut().app_theme = AppTheme::Dark;
        harness.run();
        harness.get_by_label("Dracula").simulate_click();
        harness.run();
        harness.run();
        assert!(harness.state().app_theme == AppTheme::Dracula);
        let back = WritingApp::load_library().expect("reloads");
        assert!(back.app_theme == AppTheme::Dracula);
    }

    #[test]
    fn repro_full_app_sheet_drag() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));

        // First sheet card title in the default library.
        wait_for_label(&mut harness, "Welcome");
        let node = harness.get_by_label("Welcome");
        let bounds = node.raw_bounds().expect("title label has bounds");
        let start = egui::pos2(
            ((bounds.x0 + bounds.x1) / 2.0) as f32,
            ((bounds.y0 + bounds.y1) / 2.0) as f32,
        );
        // Drop on the last card.
        wait_for_label(&mut harness, "Export Style Guide");
        let last = harness.get_by_label("Export Style Guide");
        let lb = last.raw_bounds().expect("last title has bounds");
        let end = egui::pos2(
            ((lb.x0 + lb.x1) / 2.0) as f32,
            ((lb.y0 + lb.y1) / 2.0) as f32,
        );

        let before: Vec<String> = harness
            .state()
            .sheets
            .iter()
            .map(|s| WritingApp::inferred_title(&s.content))
            .collect();

        harness
            .input_mut()
            .events
            .push(egui::Event::PointerMoved(start));
        harness.step();
        harness.input_mut().events.push(egui::Event::PointerButton {
            pos: start,
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: Default::default(),
        });
        harness.step();
        for i in 1..=10 {
            let pos = start.lerp(end, i as f32 / 10.0);
            harness
                .input_mut()
                .events
                .push(egui::Event::PointerMoved(pos));
            harness.step();
        }
        // Ghost visible? The dragged title renders twice (list + tooltip).
        // These mid-drag frames are the crashing path: same id on two
        // layers panicked egui before the ghost got its own id namespace.
        let dupes = harness.query_all_by_label("Welcome").count();
        assert!(
            dupes >= 2,
            "drag never engaged (no ghost): check coordinates"
        );
        // Release to drop and settle.
        harness.input_mut().events.push(egui::Event::PointerButton {
            pos: end,
            button: egui::PointerButton::Primary,
            pressed: false,
            modifiers: Default::default(),
        });
        harness.run();

        // The drop must land: dragging the first card onto the last one
        // always reorders.
        let after: Vec<String> = harness
            .state()
            .sheets
            .iter()
            .map(|s| WritingApp::inferred_title(&s.content))
            .collect();
        assert_ne!(
            before, after,
            "sheet drag did not reorder: drop never landed"
        );
    }

    /// Full-app regression test for group-row drags: same layer-conflict
    /// exercise as sheets but through `full_width_row` + caret tooltips.
    /// Also asserts the drop lands (group order changes).

    #[test]
    fn repro_full_app_group_drag() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        // Drag "Notes" onto the bottom half of "Drafts" (after it).
        // Row labels are "<folder-icon>  <name>"; the exact string is
        // unique (sheet previews never carry the icon).
        let notes_label = format!("{}  {}", egui_phosphor::regular::FOLDER, "Notes");
        wait_for_label(&mut harness, &notes_label);
        let node = harness.get_by_label(&notes_label);
        let bounds = node.raw_bounds().expect("group label has bounds");
        let start = egui::pos2(
            ((bounds.x0 + bounds.x1) / 2.0) as f32,
            ((bounds.y0 + bounds.y1) / 2.0) as f32,
        );
        let drafts_label = format!("{}  {}", egui_phosphor::regular::FOLDER, "Drafts");
        wait_for_label(&mut harness, &drafts_label);
        let target = harness.get_by_label(&drafts_label);
        let tb = target.raw_bounds().expect("target label has bounds");
        let end = egui::pos2(
            ((tb.x0 + tb.x1) / 2.0) as f32,
            ((tb.y0 + tb.y1) / 2.0) as f32 + 8.0,
        );

        let before: Vec<(String, Option<usize>)> = harness
            .state()
            .groups
            .iter()
            .map(|g| (g.name.clone(), g.parent))
            .collect();

        harness
            .input_mut()
            .events
            .push(egui::Event::PointerMoved(start));
        harness.step();
        harness.input_mut().events.push(egui::Event::PointerButton {
            pos: start,
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: Default::default(),
        });
        harness.step();
        for i in 1..=10 {
            let pos = start.lerp(end, i as f32 / 10.0);
            harness
                .input_mut()
                .events
                .push(egui::Event::PointerMoved(pos));
            harness.step();
        }
        let dupes = harness.query_all_by_label(&notes_label).count();
        assert!(
            dupes >= 2,
            "group drag never engaged (no ghost): check coordinates"
        );
        harness.input_mut().events.push(egui::Event::PointerButton {
            pos: end,
            button: egui::PointerButton::Primary,
            pressed: false,
            modifiers: Default::default(),
        });
        harness.run();

        let after: Vec<(String, Option<usize>)> = harness
            .state()
            .groups
            .iter()
            .map(|g| (g.name.clone(), g.parent))
            .collect();
        assert_ne!(
            before, after,
            "group drag did not move the group: drop never landed"
        );
    }

