    /// End-to-end fix flow: type a typo, put the caret inside it, take the
    /// popup's suggestion, and land on fixed text.
    #[test]
    fn grammar_fix_popup_repairs_typo() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        harness.run();

        // Focus the editor and append a typo at the end; the caret lands
        // right after it (the flagged span's edge), which opens the fix
        // popup. Nodes are re-queried per step: holding one borrows the
        // harness.
        harness
            .get_by_role(egui::accesskit::Role::MultilineTextInput)
            .focus();
        harness.step();
        harness
            .get_by_role(egui::accesskit::Role::MultilineTextInput)
            .type_text(" Teh");
        harness.step();

        // The lint runs on a background worker (never blocking typing),
        // so wait for the typo to be flagged before querying the popup.
        let mut flagged = false;
        for _ in 0..200 {
            harness.step();
            let st = harness.state();
            let sel = st.selected_sheet;
            if st
                .grammar
                .cache
                .get(&sel)
                .map(|c| !c.issues.is_empty())
                .unwrap_or(false)
            {
                flagged = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        assert!(flagged, "background lint never flagged the typo");

        // The fix popup offers the correction; taking it fixes the sheet.
        // The AccessKit node can lag the lint cache by a frame or two.
        wait_for_label(&mut harness, "→ The");
        let fix = harness.get_by_label("→ The");
        fix.click();
        harness.step();
        harness.step();

        let content = harness.state().sheets[harness.state().selected_sheet]
            .content
            .clone();
        assert!(
            content.ends_with("The"),
            "fix did not apply, content ends with: {content:?}",
        );
    }

    #[test]
    fn find_matches_case_and_overlap() {
        assert!(WritingApp::find_matches("hello", "", false).is_empty());
        assert_eq!(
            WritingApp::find_matches("Hello hello", "hello", false),
            vec![(0, 5), (6, 11)]
        );
        assert_eq!(
            WritingApp::find_matches("Hello hello", "hello", true),
            vec![(6, 11)]
        );
        // Non-overlapping: "aa" in "aaa" matches once.
        assert_eq!(WritingApp::find_matches("aaa", "aa", false), vec![(0, 2)]);
        assert!(WritingApp::find_matches("hi", "hello", false).is_empty());
    }

    #[test]
    fn replace_all_in_replaces_every_non_overlapping_hit() {
        // Basic replacement plus count.
        assert_eq!(
            WritingApp::replace_all_in("foo bar foo", "foo", "baz", false),
            ("baz bar baz".to_string(), 2)
        );
        // Case handling follows find_matches.
        assert_eq!(
            WritingApp::replace_all_in("Foo foo", "foo", "x", true),
            ("Foo x".to_string(), 1)
        );
        // Non-overlapping left to right.
        assert_eq!(
            WritingApp::replace_all_in("aaa", "aa", "b", false),
            ("ba".to_string(), 1)
        );
        // Replacements containing the query must not loop or re-match.
        assert_eq!(
            WritingApp::replace_all_in("a", "a", "aa", false),
            ("aa".to_string(), 1)
        );
        // Empty query or no hits: text untouched, count zero.
        assert_eq!(
            WritingApp::replace_all_in("abc", "", "x", false),
            ("abc".to_string(), 0)
        );
        assert_eq!(
            WritingApp::replace_all_in("abc", "z", "x", false),
            ("abc".to_string(), 0)
        );
    }

    #[test]
    fn apply_replace_at_targets_one_match() {
        let content = "aaa";
        let matches = WritingApp::find_matches(content, "a", false);
        assert_eq!(matches, vec![(0, 1), (1, 2), (2, 3)]);
        // Replacing the middle match leaves the others intact.
        let (out, next) = WritingApp::apply_replace_at(content, &matches, 1, "b");
        assert_eq!(out, "aba");
        assert_eq!(next, 1);
        // Clamped when the index is stale.
        let (out, _) = WritingApp::apply_replace_at(content, &matches, 99, "b");
        assert_eq!(out, "aab");
    }

    #[test]
    fn find_replace_then_undo_restores_content() {
        use egui::Modifiers;
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        harness.run();

        // Seed known content in the selected sheet.
        let sel = harness.state().selected_sheet;
        harness.state_mut().sheets[sel].content = "aa bb aa".to_string();
        harness.run();

        // Open the bar and set the query + replacement directly, the
        // way typing them would.
        harness.state_mut().find_open = true;
        harness.state_mut().find_query = "aa".to_string();
        harness.state_mut().find_replace = "cc".to_string();
        harness.run();
        harness.run();

        // Replace applies to the first match and moves on.
        harness.get_by_label("Replace").simulate_click();
        harness.run();
        harness.run();
        let content = harness.state().sheets[sel].content.clone();
        assert_eq!(content, "cc bb aa", "replace did not apply");

        // Cmd+Z restores the pre-replace content. The bar matches the raw
        // key event, so no global modifier state is needed.
        harness.input_mut().events.push(egui::Event::Key {
            key: egui::Key::Z,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers {
                command: true,
                ..Default::default()
            },
        });
        harness.run();
        harness.run();
        let restored = harness.state().sheets[sel].content.clone();
        assert_eq!(
            harness.state().sheets[sel].content.clone(),
            "aa bb aa",
            "undo did not restore content"
        );
    }

    #[test]
    fn fuzzy_score_ranks_better_matches_first() {
        // Non-matches and empty queries score nothing.
        assert_eq!(WritingApp::fuzzy_score("New sheet", ""), None);
        assert_eq!(WritingApp::fuzzy_score("New sheet", "xyz"), None);
        assert_eq!(WritingApp::fuzzy_score("", "a"), None);
        // Exact-case beats case-folded.
        let exact = WritingApp::fuzzy_score("Ab", "Ab").unwrap();
        let folded = WritingApp::fuzzy_score("Ab", "ab").unwrap();
        assert!(exact > folded, "exact {exact} vs folded {folded}");
        // Word starts beat mid-word matches.
        let head = WritingApp::fuzzy_score("New sheet", "ns").unwrap();
        let mid = WritingApp::fuzzy_score("Sync settings", "ns").unwrap();
        assert!(head > mid, "head {head} vs mid {mid}");
        // Consecutive runs beat scattered letters.
        let run = WritingApp::fuzzy_score("abc", "ab").unwrap();
        let scattered = WritingApp::fuzzy_score("aXb", "ab").unwrap();
        assert!(run > scattered, "run {run} vs scattered {scattered}");
        // The motivating case: "st" prefers a style entry over a
        // mid-word scatter in a longer title.
        let style = WritingApp::fuzzy_score("Style suggestions", "st").unwrap();
        let scattered_title = WritingApp::fuzzy_score("Export Style Guide", "st").unwrap();
        assert!(
            style > scattered_title,
            "style {style} vs scattered {scattered_title}"
        );
    }

    #[test]
    fn paragraph_at_selects_blank_line_blocks() {
        // Two paragraphs plus a trailing blank line.
        let text = "First.\nStill first.\n\nSecond.";
        // Inside the first block.
        assert_eq!(WritingApp::paragraph_at(text, 0), (0, 19));
        assert_eq!(WritingApp::paragraph_at(text, 10), (0, 19));
        // On the blank line: just that line.
        assert_eq!(WritingApp::paragraph_at(text, 20), (20, 20));
        // Second block to end of text (clamped).
        assert_eq!(WritingApp::paragraph_at(text, 21), (21, 28));
        assert_eq!(WritingApp::paragraph_at(text, 100), (21, 28));
    }

