    /// Right-click a group row, pick Rename, type a name, press Enter:
    /// the group is renamed in place.
    #[test]
    fn group_rename_menu_to_header_editor() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));

        // Group row label carries the folder icon prefix.
        let label = format!("{}  {}", egui_phosphor::regular::FOLDER, "Notes");
        wait_for_label(&mut harness, &label);
        let node = harness.get_by_label(&label);
        let bounds = node.raw_bounds().expect("group row has bounds");
        let at = egui::pos2(
            ((bounds.x0 + bounds.x1) / 2.0) as f32,
            ((bounds.y0 + bounds.y1) / 2.0) as f32,
        );
        // Secondary press + release opens the row context menu.
        harness
            .input_mut()
            .events
            .push(egui::Event::PointerMoved(at));
        harness.step();
        for pressed in [true, false] {
            harness.input_mut().events.push(egui::Event::PointerButton {
                pos: at,
                button: egui::PointerButton::Secondary,
                pressed,
                modifiers: Default::default(),
            });
            harness.step();
        }
        harness.run();
        wait_for_label(&mut harness, "Rename group");
        harness.get_by_label("Rename group").simulate_click();
        harness.run();
        // Sheets header now edits the name; the draft is pre-selected so
        // typing replaces it, and Enter commits.
        harness
            .input_mut()
            .events
            .push(egui::Event::Text("Projects".to_string()));
        harness.step();
        harness.input_mut().events.push(egui::Event::Key {
            key: egui::Key::Enter,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Default::default(),
        });
        harness.step();
        harness.run();
        assert_eq!(harness.state().groups[0].name, "Projects");
        assert!(harness.state().group_rename.is_none());
    }

    /// Creating a group drops straight into naming it in the sheets
    /// header: typing replaces the default name.
    #[test]
    fn new_group_prompts_for_name() {
        use egui_kittest::kittest::Queryable as _;
        use egui_kittest::Harness;

        let _storage = isolate_storage();
        let mut harness = Harness::new_eframe(|cc| WritingApp::new(cc, None));
        harness.set_size(egui::vec2(1100.0, 720.0));
        harness.run();

        let before = harness.state().groups.len();
        // Drive creation the same way the section "+" button does.
        let idx = harness.state_mut().add_group(Section::Documents);
        if let Some(g) = harness.state().groups.get(idx) {
            let (id, name) = (g.id.clone(), g.name.clone());
            harness.state_mut().start_group_rename(id, name);
        }
        harness.run();
        assert_eq!(harness.state().groups.len(), before + 1);
        assert!(harness.state().group_rename.is_some());
        harness
            .input_mut()
            .events
            .push(egui::Event::Text("Fresh".to_string()));
        harness.step();
        harness.input_mut().events.push(egui::Event::Key {
            key: egui::Key::Enter,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Default::default(),
        });
        harness.step();
        harness.run();
        let names: Vec<String> = harness
            .state()
            .groups
            .iter()
            .map(|g| g.name.clone())
            .collect();
        assert!(
            names.contains(&"Fresh".to_string()),
            "renamed group missing, got {names:?}"
        );
    }

    // ---- Keyboard navigation (H1) -------------------------------------

    #[test]
    fn keyboard_navigation_walks_library_and_sheet_lists() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.selection = SidebarSelection::Filter(SmartFilter::All);
        app.selected_sheet = 0;
        app.pane_focus = PaneFocus::Library;

        // Down moves through the smart filters before groups.
        app.move_library_selection(1);
        assert_eq!(
            app.selection,
            SidebarSelection::Filter(SmartFilter::Last7Days)
        );
        app.move_library_selection(3);
        assert_eq!(app.selection, SidebarSelection::Filter(SmartFilter::Trash));
        // A filter with no sheets keeps the editor selection sane.
        app.move_library_selection(-4);
        assert_eq!(app.selection, SidebarSelection::Filter(SmartFilter::All));

        // Entries include every visible group after the filters. iCloud is
        // hidden on platforms that do not expose it (Linux CI).
        let entries = app.library_nav_entries();
        assert!(entries.contains(&SidebarSelection::Group(0)));
        assert_eq!(
            entries
                .iter()
                .filter(|e| matches!(e, SidebarSelection::Filter(_)))
                .count(),
            5
        );

        // The sheets cursor follows the visible list.
        let visible = app.visible_sheets();
        assert_eq!(visible, vec![0, 1]);
        app.selected_sheet = visible[0];
        app.move_sheet_selection(1);
        assert_eq!(app.selected_sheet, 1);
        app.move_sheet_selection(-1);
        assert_eq!(app.selected_sheet, 0);
    }

    #[test]
    fn editor_widget_ids_follow_sheet_uuid_not_index() {
        let mut app = sample_app();
        let first = app.sheets[0].id.clone();
        let second = app.sheets[1].id.clone();
        assert_eq!(
            app.editor_widget_id(0),
            WritingApp::editor_widget_id_for(&first)
        );
        assert_eq!(
            app.editor_widget_id(1),
            WritingApp::editor_widget_id_for(&second)
        );
        // Moving a sheet to another list position must move its widget id
        // with it (this is what keeps egui's undo stack on the right text).
        app.sheets.swap(0, 1);
        assert_eq!(
            app.editor_widget_id(0),
            WritingApp::editor_widget_id_for(&second)
        );
        assert_eq!(
            app.editor_widget_id(1),
            WritingApp::editor_widget_id_for(&first)
        );
    }

    // ---- Table of contents export (H2) --------------------------------

    #[test]
    fn toc_marker_expands_to_linked_headings() {
        let content = "# Book\n\n(toc)\n\n## One\n\nBody\n\n## Two Words\n\nMore\n";
        let blocks = WritingApp::parse_blocks(content);
        assert!(blocks
            .iter()
            .any(|b| matches!(b, Block::Heading(1, t) if t == "Contents")));
        assert!(blocks.iter().any(|b| matches!(
            b,
            Block::Bullet(t) if t == "[One](#one)"
        )));
        assert!(blocks.iter().any(|b| matches!(
            b,
            Block::Bullet(t) if t == "[Two Words](#two-words)"
        )));

        let md = WritingApp::expand_toc_markdown(content);
        assert!(md.contains("## Contents"));
        assert!(md.contains("- [One](#one)"));
        assert!(md.contains("- [Two Words](#two-words)"));
        // The leading sheet title is not repeated in its own contents.
        assert!(!md.contains("[Book](#book)"));
    }

    #[test]
    fn toc_marker_ignored_inside_code_fences() {
        let content = "```\n(toc)\n```\n## Real\n";
        let md = WritingApp::expand_toc_markdown(content);
        assert!(md.contains("(toc)"));
        assert!(!md.contains("## Contents"));
        assert!(!WritingApp::parse_blocks(content)
            .iter()
            .any(|b| matches!(b, Block::Bullet(_))));
    }

