    #[test]
    fn created_dates_record_and_correct_across_save_load() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.create_sheet();
        let idx = app.selected_sheet;
        let id = app.sheets[idx].id.clone();
        assert!(app.created_dates.contains_key(&id));
        let corrected = super::parse_created_date("2015-06-01").unwrap();
        app.set_sheet_created(idx, corrected);
        assert_eq!(
            super::format_created_date(app.sheet_created(idx)),
            "2015-06-01"
        );
        app.save_library();
        let loaded = WritingApp::load_library().expect("library roundtrip");
        assert_eq!(
            super::format_created_date(
                loaded
                    .created_dates
                    .get(&id)
                    .copied()
                    .expect("created date persisted")
            ),
            "2015-06-01"
        );
    }

