    #[test]
    fn markdown_tables_parse_with_alignment_and_rows() {
        let content = "# Doc\n\n| Name | Qty |\n| :--- | ---: |\n| A | 2 |\n| B | 3 |\n";
        let blocks = WritingApp::parse_blocks(content);
        let table = blocks
            .iter()
            .find_map(|b| match b {
                Block::Table {
                    headers,
                    rows,
                    aligns,
                } => Some((headers, rows, aligns)),
                _ => None,
            })
            .expect("table block");
        assert_eq!(table.0, &vec!["Name".to_string(), "Qty".to_string()]);
        assert_eq!(table.1.len(), 2);
        assert_eq!(table.1[0], vec!["A".to_string(), "2".to_string()]);
        assert_eq!(table.2, &vec![ExportAlign::Left, ExportAlign::Right]);
    }

    #[test]
    fn table_at_finds_the_table_under_the_caret_and_roundtrips() {
        let content = "# T\n\n| A | B |\n| :--- | ---: |\n| 1 | 2 |\n\nafter\n";
        let caret = content.find("1 | 2").unwrap() + 1;
        let (start, end, headers, rows, aligns) =
            WritingApp::table_at(content, caret).expect("table under caret");
        assert_eq!(headers, vec!["A".to_string(), "B".to_string()]);
        assert_eq!(rows, vec![vec!["1".to_string(), "2".to_string()]]);
        assert_eq!(aligns, vec![ExportAlign::Left, ExportAlign::Right]);
        let md = WritingApp::table_markdown(&headers, &rows, &aligns);
        assert!(md.contains("| --- | ---: |"));
        assert_eq!(
            &content[start..end],
            "| A | B |\n| :--- | ---: |\n| 1 | 2 |\n"
        );
    }

