    // ---- LaTeX equations (L7) -----------------------------------------

    #[test]
    fn latex_to_unicode_converts_common_notation() {
        assert_eq!(WritingApp::latex_to_unicode("\\frac{1}{2}"), "1/2");
        assert_eq!(WritingApp::latex_to_unicode("\\sqrt{x^2+y^2}"), "√(x²+y²)");
        assert_eq!(
            WritingApp::latex_to_unicode("\\alpha \\leq \\beta"),
            "α ≤ β"
        );
        assert_eq!(WritingApp::latex_to_unicode("\\sum_{i=1}^{n} i"), "∑ᵢ₌₁ⁿ i");
        assert_eq!(WritingApp::latex_to_unicode("\\infty"), "∞");
    }

    #[test]
    fn display_and_inline_math_reach_blocks_and_exports() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.sheets[0].content =
            "# Math\n\nInline $\\alpha^2 + \\beta$ text.\n\n$$\n\\frac{a}{b} \\leq \\infty\n$$\n"
                .to_string();
        let blocks = WritingApp::parse_blocks(&app.sheets[0].content);
        assert!(blocks
            .iter()
            .any(|b| matches!(b, Block::Math(t) if t == "a/b ≤ ∞")));
        let para = blocks
            .iter()
            .find_map(|b| match b {
                Block::Para(t) if t.contains("Inline") => Some(t),
                _ => None,
            })
            .expect("inline paragraph");
        let plain = WritingApp::spans_plain(&WritingApp::parse_spans(para));
        assert!(plain.contains("α² + β"));

        let html = app.export_html(&[0]);
        assert!(html.contains("α² + β"));
        assert!(html.contains("class=\"math\""));
        // Markdown keeps the editable LaTeX source.
        let md = app.export_markdown(&[0]);
        assert!(md.contains("$\\alpha^2 + \\beta$"));
        // The display equation also reaches the other exporters.
        assert!(app.export_rtf(&[0]).contains("a/b"));
        assert!(app
            .export_docx_bytes(&[0])
            .windows("a/b ≤ ∞".len())
            .any(|w| w == "a/b ≤ ∞".as_bytes()));
    }

