    #[test]
    fn keyword_manager_renames_merges_deletes_and_colors() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.sheets[0].keywords = vec!["draft".to_string(), "theme".to_string()];
        app.sheets[1].keywords = vec!["draft".to_string()];
        let counts = app.keyword_counts();
        assert_eq!(counts.get("draft"), Some(&2));
        assert_eq!(counts.get("theme"), Some(&1));

        app.set_keyword_color("draft", Some("#61afef".to_string()));
        app.toggle_keyword_favorite("draft");

        app.rename_keyword("draft", "idea");
        assert_eq!(app.keyword_counts().get("draft"), None);
        assert_eq!(app.keyword_counts().get("idea"), Some(&2));
        let style = app.keyword_styles.get("idea").expect("style moved");
        assert_eq!(style.color.as_deref(), Some("#61afef"));
        assert!(style.favorite);

        // Merging dedupes: sheet 0 already had "theme".
        app.merge_keyword("idea", "theme");
        assert_eq!(app.keyword_counts().get("idea"), None);
        assert_eq!(app.keyword_counts().get("theme"), Some(&2));
        assert_eq!(app.sheets[0].keywords, vec!["theme".to_string()]);
        assert_eq!(app.sheets[1].keywords, vec!["theme".to_string()]);
        assert!(app.keyword_styles.get("idea").is_none());

        app.save_library();
        let loaded = WritingApp::load_library().expect("library roundtrip");
        assert_eq!(
            loaded
                .keyword_styles
                .get("theme")
                .map(|s| s.favorite)
                .unwrap_or(false),
            false
        );

        app.delete_keyword("theme");
        assert!(app.keyword_counts().is_empty());
        assert!(app.keyword_styles.get("theme").is_none());
    }

