    #[test]
    fn daily_goal_deadline_and_history_persist_and_calculate() {
        let _storage = isolate_storage();
        let mut app = sample_app();
        app.daily_goal = 500;
        let today = WritingApp::today_key();
        app.daily_words.insert(today.clone(), 250);
        assert_eq!(app.today_daily_words(), 250);

        let target = app.total_library_words() + 1000;
        app.deadline_target = target as u32;
        app.deadline = Some(SystemTime::now() + Duration::from_secs(10 * 86_400));
        let days = app.deadline_days_left().expect("deadline");
        // A local-date deadline ten days out can read as 9–11 calendar
        // days depending on the time of day.
        assert!((9..=11).contains(&days), "unexpected days left: {days}");
        let required = app.required_daily_words().expect("required output");
        assert!(required >= 80 && required <= 120, "required: {required}");
        assert!(app.total_library_words() >= 2);

        app.save_library();
        let loaded = WritingApp::load_library().expect("library roundtrip");
        assert_eq!(loaded.daily_goal, 500);
        assert_eq!(loaded.deadline_target, target as u32);
        assert_eq!(loaded.daily_words.get(&today).copied().unwrap_or(0), 250);
        assert!(loaded.deadline.is_some());
    }

    // ---- Focus scopes (L2) --------------------------------------------

    #[test]
    fn focus_scope_ranges_cover_line_and_sentence() {
        let content = "First sentence. Second one!\nSecond line here.";
        let chars: Vec<char> = content.chars().collect();
        let second_start = content.find("Second one").unwrap();
        let second_char = content[..second_start].chars().count();
        let (start, end) = WritingApp::sentence_at(content, second_char + 3);
        let sentence: String = chars[start..end].iter().collect();
        assert_eq!(sentence, "Second one!");
        let (ls, le) = WritingApp::line_at(content, chars.len() - 2);
        let line: String = chars[ls..le].iter().collect();
        assert_eq!(line, "Second line here.");

        let line_range = WritingApp::focus_scope_range(content, second_char + 3, FocusScope::Line);
        let sentence_range =
            WritingApp::focus_scope_range(content, second_char + 3, FocusScope::Sentence);
        assert_eq!(line_range, (0, content.find('\n').unwrap()));
        assert_eq!(sentence_range, (start, end));
    }

